use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl UniverseIndex { pub const ROOT : UniverseIndex = UniverseIndex :: ZERO ; # [doc = " Returns the \"next\" universe index in order -- this new index"] # [doc = " is considered to extend all previous universes. This"] # [doc = " corresponds to entering a `forall` quantifier. So, for"] # [doc = " example, suppose we have this type in universe `U`:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " for<'a> fn(&'a u32)"] # [doc = " ```"] # [doc = ""] # [doc = " Once we \"enter\" into this `for<'a>` quantifier, we are in a"] # [doc = " new universe that extends `U` -- in this new universe, we can"] # [doc = " name the region `'a`, but that region was not nameable from"] # [doc = " `U` because it was not in scope there."] pub fn next_universe (self) -> UniverseIndex { UniverseIndex :: from_u32 (self . as_u32 () . checked_add (1) . unwrap ()) } # [doc = " Returns `true` if `self` can name a name from `other` -- in other words,"] # [doc = " if the set of names in `self` is a superset of those in"] # [doc = " `other` (`self >= other`)."] pub fn can_name (self , other : UniverseIndex) -> bool { self >= other } # [doc = " Returns `true` if `self` cannot name some names from `other` -- in other"] # [doc = " words, if the set of names in `self` is a strict subset of"] # [doc = " those in `other` (`self < other`)."] pub fn cannot_name (self , other : UniverseIndex) -> bool { self < other } # [doc = " Returns `true` if `self` is the root universe, otherwise false."] pub fn is_root (self) -> bool { self == Self :: ROOT } }
}